import { createTenant } from '@projexlight/sdk-tenant';
const t = await createTenant({
  app_id: 'acme-app',
  display_name: 'Acme Corp',
  region: 'us-east-1',
  isolation_tier: 'S',
  module_subscriptions: ['crm', 'billing', 'audit'],
});

import { attachReseller } from '@projexlight/sdk-tenant';
const t = await attachReseller(tenant_id, reseller_id, {
  commission_rules: { pct: 15, tier: 'gold' },
});

import { createSubTenant } from '@projexlight/sdk-tenant';
const sub = await createSubTenant(parent_tenant_id, {
  app_id: parent.app_id,
  display_name: 'Regulated BU',
  region: parent.region,
  module_subscriptions: parent.module_subscriptions,
}, { placement: 'tier-p' });

import { createBu } from '@projexlight/sdk-tenant';
const region = await createBu(tenant_id, { name: 'North America', kind: 'region' });
const sales = await createBu(tenant_id, { name: 'Sales', kind: 'cost-center', parent_bu_id: region.bu_id });

import { setFiscalCalendar } from '@projexlight/sdk-tenant';
const periods = await setFiscalCalendar(tenant_id, {
  year_start_month: 4,
  base_currency: 'USD',
});
